CREATE OR ALTER PROCEDURE [dbo].[uspOrder_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @ContractId UNIQUEIDENTIFIER = NULL
	, @DeliveryLocationId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @OrderNumber NVARCHAR(MAX) = NULL
	, @OrderDate DATETIME = NULL
	, @DeliveryDate DATETIME2 = NULL
	, @TotalQuantity DECIMAL(18,6) = NULL
	, @TotalAmount DECIMAL(18,2) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @FromMealDate DATE = NULL -- UI-2 (D-66 f3): lọc theo ngày ăn từ – đến
	, @ToMealDate DATE = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[CustomerId]
			, j1.[DisplayName] AS [CustomerName]
			, t.[ContractId]
			, j2.[Name] AS [ContractName]
			, t.[DeliveryLocationId]
			, t.[OrderDate]
			, t.[MealDate]
			, t.[Status]
			, t.[TotalQuantity]
			, t.[TotalAmount]
			, t.[Note]
			, t.[OrderNumber]
			, t.[DeliveryDate]
			, t.[CreatedDate]
		FROM [dbo].[Order] AS t
		LEFT JOIN [dbo].[Customer] AS j1 ON j1.[Id] = t.[CustomerId]
		LEFT JOIN [dbo].[Contract] AS j2 ON j2.[Id] = t.[ContractId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[OrderNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (@ContractId IS NULL OR t.[ContractId] = @ContractId)
			AND (@DeliveryLocationId IS NULL OR t.[DeliveryLocationId] = @DeliveryLocationId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@OrderNumber, '') = '' OR t.[OrderNumber] LIKE CONCAT('%', @OrderNumber, '%'))
			AND (@OrderDate IS NULL OR t.[OrderDate] = @OrderDate)
			AND (@DeliveryDate IS NULL OR t.[DeliveryDate] = @DeliveryDate)
			AND (@TotalQuantity IS NULL OR t.[TotalQuantity] = @TotalQuantity)
			AND (@TotalAmount IS NULL OR t.[TotalAmount] = @TotalAmount)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND (@FromMealDate IS NULL OR t.[MealDate] >= @FromMealDate)
			AND (@ToMealDate IS NULL OR t.[MealDate] < DATEADD(DAY, 1, @ToMealDate))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerName' THEN r.[CustomerName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerName' THEN r.[CustomerName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contractId' THEN r.[ContractId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contractId' THEN r.[ContractId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contractName' THEN r.[ContractName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contractName' THEN r.[ContractName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryLocationId' THEN r.[DeliveryLocationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryLocationId' THEN r.[DeliveryLocationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderDate' THEN r.[OrderDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderDate' THEN r.[OrderDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'mealDate' THEN r.[MealDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'mealDate' THEN r.[MealDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'totalQuantity' THEN r.[TotalQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'totalQuantity' THEN r.[TotalQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'totalAmount' THEN r.[TotalAmount] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'totalAmount' THEN r.[TotalAmount] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderNumber' THEN r.[OrderNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderNumber' THEN r.[OrderNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryDate' THEN r.[DeliveryDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryDate' THEN r.[DeliveryDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
